// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 _value) public {
        bound(_value, 1, type(uint128).max);

        vm.deal(address(c), _value);

        bool ok;
        uint256 balanceBefore = address(c).balance;
        try c.withdraw(_value) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;

        assertTrue(!ok || balanceBefore - balanceAfter == _value);
    }
}
